//! The app icon and logo, generated by scripts/make-icons.sh from assets/icon/.

use std::sync::OnceLock;

/// 512 px app icon on the macOS grid: the Dock icon while running (also when not
/// started from the app bundle, e.g. scripts/dev.sh).
pub const APP_ICON_PNG: &[u8] = include_bytes!("../assets/app-icon.png");
const LOGO_PNG: &[u8] = include_bytes!("../assets/logo.png");

/// The logo mark (transparent, square), decoded once.
pub fn logo() -> &'static rune::Pixels {
    static LOGO: OnceLock<rune::Pixels> = OnceLock::new();
    LOGO.get_or_init(|| {
        let px = rune::Pixels::new();
        if let Some((w, h, rgba)) = decode_rgba(LOGO_PNG) {
            px.set(w, h, rgba);
        }
        px
    })
}

/// An 8-bit RGB or RGBA PNG as straight-alpha RGBA.
fn decode_rgba(bytes: &[u8]) -> Option<(u32, u32, Vec<u8>)> {
    let mut dec = png::Decoder::new(std::io::Cursor::new(bytes));
    dec.set_transformations(png::Transformations::EXPAND | png::Transformations::STRIP_16);
    let mut reader = dec.read_info().ok()?;
    let mut buf = vec![0; reader.output_buffer_size()];
    let info = reader.next_frame(&mut buf).ok()?;
    buf.truncate(info.buffer_size());
    let rgba = match info.color_type {
        png::ColorType::Rgba => buf,
        png::ColorType::Rgb => buf.chunks_exact(3).flat_map(|c| [c[0], c[1], c[2], 255]).collect(),
        _ => return None,
    };
    Some((info.width, info.height, rgba))
}

#[cfg(test)]
mod tests {
    #[test]
    fn assets_decode() {
        let (w, h, px) = super::decode_rgba(super::LOGO_PNG).expect("logo decodes");
        assert_eq!((w, h, px.len()), (256, 256, 256 * 256 * 4));
        assert!(super::decode_rgba(super::APP_ICON_PNG).is_some());
    }
}
